func hdStylePoints(sf *port.Cells, sc *port.Cells, l int32) int32 {
	// How far the line's style stands out from the body's: bigger (3, 4), bold (3), capitals (2), italic
	// (1), another colour (1). -1 when it cannot be a heading by style: monospaced against a body that is
	// not, or smaller than the body with neither weight nor capitals to say it is more, not less.
	var body int32 = style.StHget(sf, style.SfhBody())
	var bsz int32 = style.StHget(sf, style.SfhSize())
	var sz int32 = style.StGet(sf, l, style.SfkSize())
	var bits int32 = style.StGet(sf, l, style.SfkBits())
	var bbits int32 = style.ScGet(sc, body, style.SckBits())
	var col int32 = style.StGet(sf, l, style.SfkColor())
	var bcol int32 = style.ScGet(sc, body, style.SckColor())
	var p int32 = 0
	var weight int32 = 0
	if ((bits & 64) != 0) && ((bbits & 64) == 0) {
		return -1
	}
	if (sz * 100) >= (bsz * 104) {
		p += 3
	}
	if (sz * 100) >= (bsz * 120) {
		p += 1
	}
	if ((bits & 1) != 0) && ((bbits & 1) == 0) {
		p += 3
		weight = 1
	}
	if (style.StGet(sf, l, style.SfkCaps()) == 1) && (style.ScGet(sc, body, style.SckCaps()) == 0) {
		p += 2
		weight = 1
	}
	if ((bits & 2) != 0) && ((bbits & 2) == 0) {
		p += 1
	}
	if (col >= 0) && ((bcol >= 0) && (col != bcol)) {
		p += 1
	}
	if ((sz * 100) <= (bsz * 96)) && (weight == 0) {
		return -1
	}
	return p
}

