func hdPartner(wd *port.Cells, ln *port.Cells, et *port.Cells, ws *port.Cells, sf *port.Cells, l int32) int32 {
	// The line that is the other half of line l's heading line, or -1: l and its one sibling on the row are
	// alone with each other, of one size, a number's width apart (ten ems at most), and one of them is a bare
	// numbering pattern standing left of the other.
	var q int32 = style.StGet(sf, l, style.SfkSibline())
	if q < 0 {
		return -1
	}
	if (style.StGet(sf, l, style.SfkNsib()) != 1) || (style.StGet(sf, q, style.SfkNsib()) != 1) {
		return -1
	}
	if style.StGet(sf, q, style.SfkSibline()) != l {
		return -1
	}
	if (style.StGet(sf, l, style.SfkClass()) < 0) || (style.StGet(sf, q, style.SfkClass()) < 0) {
		return -1
	}
	if style.StGet(sf, l, style.SfkBucket()) != style.StGet(sf, q, style.SfkBucket()) {
		return -1
	}
	if style.StGet(sf, l, style.SfkSibgap()) > (10 * style.StGet(sf, l, style.SfkSize())) {
		return -1
	}
	var lm int32 = hdMarkerOnly(wd, ln, et, ws, l)
	var qm int32 = hdMarkerOnly(wd, ln, et, ws, q)
	if lm == qm {
		return -1
	}
	if lm == 1 {
		if style.StGet(sf, l, style.SfkX0()) >= style.StGet(sf, q, style.SfkX0()) {
			return -1
		}
	} else if style.StGet(sf, q, style.SfkX0()) >= style.StGet(sf, l, style.SfkX0()) {
		return -1
	}
	return q
}

